<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {ElMessage} from 'element-plus'
import {api,fmt} from '../api'
import {useWorkspace} from '../store'
import Icon from '../components/Icon.vue'
const store=useWorkspace(),tab=ref('keys'),keys=ref<any[]>([]),users=ref<any[]>([]),organizations=ref<any[]>([]),events=ref<any[]>([]),total=ref(0),page=ref(1),config=ref<any>({}),newKey=ref(''),keyName=ref(''),readOnly=ref(true),username=ref(''),password=ref(''),orgName=ref(''),orgUsers=ref<number[]>([]),orgProjects=ref<number[]>([]),globalKnowledge=ref('[]')
async function load(){keys.value=(await api.get('access-keys/')).data;if(store.user.is_admin){users.value=(await api.get('system/users/')).data;organizations.value=(await api.get('system/organizations/')).data;config.value=(await api.get('system/config/')).data;globalKnowledge.value=JSON.stringify(config.value.global_knowledge_ids);await logs()}}
async function logs(){const {data}=await api.get('system/audit/',{params:{page:page.value}});events.value=data.results;total.value=data.count}
async function createKey(){const {data}=await api.post('access-keys/',{project:store.projectId,name:keyName.value||'项目访问密钥',read_only:readOnly.value});newKey.value=data.key;await load()}
async function revoke(id:number){await api.delete('access-keys/',{data:{id}});ElMessage.success('密钥已撤销');load()}
async function createUser(){await api.post('system/users/',{username:username.value,password:password.value});username.value='';password.value='';ElMessage.success('用户已创建');load()}
async function toggle(user:any){await api.patch('system/users/',{id:user.id,is_active:!user.is_active});load()}
async function saveOrg(){await api.post('system/organizations/',{name:orgName.value,users:orgUsers.value,projects:orgProjects.value});ElMessage.success('组织已保存');load()}
async function saveConfig(){let ids;try{ids=JSON.parse(globalKnowledge.value)}catch{ElMessage.warning('知识库 ID 需为 JSON 数组');return}await api.patch('system/config/',{...config.value,global_knowledge_ids:ids});ElMessage.success('配置已保存');load()}
onMounted(load)
</script>
<template><div><div class="page-heading"><div><div class="heading-eyebrow">ADMINISTRATION & GOVERNANCE</div><h1>{{ $t('系统管理') }}</h1><p>{{ $t('管理用户、组织、项目访问密钥与平台审计。') }}</p></div><span class="mini-badge">TestPilot 2.0.0</span></div><section class="panel system-panel"><el-tabs v-model="tab"><el-tab-pane label="API Key" name="keys"><h3>{{ $t('项目访问密钥') }}</h3><p class="helper">{{ $t('密钥只显示一次，有效期 30 天，限制在当前项目，继承账号在该项目中的权限。') }}</p><div class="inline-actions"><el-input v-model="keyName" :placeholder="$t('密钥名称')" style="width:250px"/><el-checkbox v-model="readOnly">{{ $t('只读') }}</el-checkbox><el-button type="primary" :disabled="!store.projectId" @click="createKey">{{ $t('创建密钥') }}</el-button></div><el-alert v-if="newKey" :title="newKey" :description="$t('请立即保存，关闭后无法再次查看完整密钥。')" type="success" @close="newKey=''" style="margin-top:20px"/><el-table :data="keys"><el-table-column prop="name" :label="$t('名称')"/><el-table-column prop="prefix" :label="$t('前缀')"/><el-table-column :label="$t('范围')"><template #default="{row}">项目 #{{row.project}} · {{row.read_only?'只读':'可写'}}</template></el-table-column><el-table-column :label="$t('过期时间')"><template #default="{row}">{{fmt(row.expires_at)}}</template></el-table-column><el-table-column :label="$t('操作')"><template #default="{row}"><el-button link type="danger" @click="revoke(row.id)">{{ $t('撤销') }}</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane v-if="store.user.is_admin" :label="$t('用户管理')" name="users"><div class="inline-actions"><el-input v-model="username" :placeholder="$t('用户名')" style="width:200px"/><el-input v-model="password" type="password" show-password :placeholder="$t('初始密码')" autocomplete="new-password" style="width:240px"/><el-button type="primary" @click="createUser">{{ $t('创建用户') }}</el-button></div><p class="helper">{{ $t('创建后在项目管理中分配编辑者或观察者权限。停用账号会立即阻止登录与 API Key 使用。') }}</p><el-table :data="users"><el-table-column prop="username" :label="$t('用户名')"/><el-table-column :label="$t('角色')"><template #default="{row}">{{row.is_superuser?'系统管理员':'普通用户'}}</template></el-table-column><el-table-column :label="$t('状态')"><template #default="{row}">{{row.is_active?'启用':'停用'}}</template></el-table-column><el-table-column :label="$t('操作')"><template #default="{row}"><el-button v-if="row.id!==store.user.id" link @click="toggle(row)">{{row.is_active?'停用':'启用'}}</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane v-if="store.user.is_admin" :label="$t('组织管理')" name="org"><p class="helper">{{ $t('组织用于归档团队与项目；数据访问仍以项目成员权限为准，不因加入组织自动扩大权限。') }}</p><el-form label-position="top"><el-form-item :label="$t('组织名称')"><el-input v-model="orgName"/></el-form-item><el-form-item :label="$t('组织成员')"><el-select v-model="orgUsers" multiple><el-option v-for="u in users" :key="u.id" :label="u.username" :value="u.id"/></el-select></el-form-item><el-form-item :label="$t('组织项目')"><el-select v-model="orgProjects" multiple><el-option v-for="p in store.projects" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><el-button type="primary" @click="saveOrg">{{ $t('保存组织') }}</el-button></el-form><el-table :data="organizations"><el-table-column prop="name" :label="$t('组织')"/><el-table-column :label="$t('成员')"><template #default="{row}">{{row.users.length}}</template></el-table-column><el-table-column :label="$t('项目')"><template #default="{row}">{{row.projects.length}}</template></el-table-column><el-table-column :label="$t('操作')"><template #default="{row}"><el-button link @click="orgName=row.name;orgUsers=row.users;orgProjects=row.projects">{{ $t('编辑') }}</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane v-if="store.user.is_admin" :label="$t('操作审计')" name="audit"><el-table :data="events"><el-table-column prop="user" :label="$t('用户')" width="120"/><el-table-column prop="action" :label="$t('操作')"/><el-table-column prop="target" :label="$t('目标')"/><el-table-column :label="$t('时间')" width="150"><template #default="{row}">{{fmt(row.created_at)}}</template></el-table-column></el-table><div class="pagination"><span>共 {{total}} 条</span><el-pagination v-model:current-page="page" :total="total" layout="prev,pager,next" @current-change="logs"/></div></el-tab-pane>
<el-tab-pane v-if="store.user.is_admin" :label="$t('全局配置')" name="config"><el-form label-position="top" style="max-width:600px"><el-form-item :label="$t('操作日志保留天数')"><el-input-number v-model="config.audit_retention_days" :min="7" :max="3650"/></el-form-item><el-form-item :label="$t('可用版本（内网管理员发布）')"><el-input v-model="config.available_version"/></el-form-item><el-alert v-if="config.available_version&&config.available_version!==config.current_version" :title="`有可用版本 ${config.available_version}，当前 ${config.current_version}`" type="info" :closable="false"/><el-form-item :label="$t('全局默认知识库 ID（仍校验项目权限）')"><el-input v-model="globalKnowledge"/></el-form-item><el-button type="primary" @click="saveConfig">{{ $t('保存配置') }}</el-button></el-form><p class="helper">{{ $t('日志清理：python backend/manage.py cleanup_audit。模型、嵌入与 Reranker 地址在模型管理中配置；连接测试在模型卡片中发起。') }}</p><pre class="json-result">{{JSON.stringify(config.adapters,null,2)}}</pre></el-tab-pane></el-tabs></section></div></template>
